"use client";
// Adapted from shadcn/ui (MIT). Same Radix API; retained panels and one marker.
import * as React from "react";
import { Tabs as Primitive } from "./primitive-tabs";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import "./tabs.css";
const Selection = React.createContext<string | undefined>(undefined);
function Tabs({
  className,
  value,
  defaultValue,
  onValueChange,
  ...props
}: React.ComponentProps<typeof Primitive.Root>) {
  const [internal, setInternal] = React.useState(defaultValue);
  const selected = value === undefined ? internal : value;
  return (
    <Selection.Provider value={selected}>
      <Primitive.Root
        {...props}
        className={cn("roc-ui", className)}
        data-slot="tabs"
        value={selected}
        onValueChange={(next) => {
          if (value === undefined) setInternal(next);
          onValueChange?.(next);
        }}
      />
    </Selection.Provider>
  );
}
const tabsListVariants = cva("roc-ui", {
  variants: {
    variant: { default: "roc-ui-tabs-default", line: "roc-ui-tabs-line" },
  },
  defaultVariants: { variant: "default" },
});
function TabsList({
  className,
  variant = "default",
  children,
  ...props
}: React.ComponentProps<typeof Primitive.List> &
  VariantProps<typeof tabsListVariants>) {
  const marker = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const node = marker.current!,
      list = node.parentElement!;
    let ready = false;
    const measure = () => {
      const active = list.querySelector<HTMLElement>(
        '[role="tab"][data-state="active"]',
      );
      if (!active) {
        node.hidden = true;
        return;
      }
      node.hidden = false;
      node.style.width = `${active.offsetWidth}px`;
      node.style.height = `${active.offsetHeight}px`;
      node.style.transform = `translate(${active.offsetLeft}px,${active.offsetTop}px)`;
      if (!ready) {
        node.getBoundingClientRect();
        node.dataset.ready = "true";
        ready = true;
      }
    };
    measure();
    const resize = new ResizeObserver(measure);
    resize.observe(list);
    Array.from(list.children)
      .filter((n) => n !== node)
      .forEach((n) => resize.observe(n));
    const mutation = new MutationObserver(measure);
    mutation.observe(list, {
      subtree: true,
      attributes: true,
      attributeFilter: ["data-state"],
    });
    return () => {
      resize.disconnect();
      mutation.disconnect();
    };
  }, []);
  // The observer measures Radix's committed selection, including controlled updates.
  return (
    <Primitive.List
      {...props}
      data-slot="tabs-list"
      data-variant={variant}
      className={cn(tabsListVariants({ variant }), className)}
    >
      <span ref={marker} className="roc-ui-tabs-marker" aria-hidden="true" />
      {children}
    </Primitive.List>
  );
}
function TabsTrigger({
  className,
  ...props
}: React.ComponentProps<typeof Primitive.Trigger>) {
  return (
    <Primitive.Trigger
      {...props}
      data-slot="tabs-trigger"
      className={cn("roc-ui", className)}
    />
  );
}
function TabsContent({
  className,
  value,
  ...props
}: React.ComponentProps<typeof Primitive.Content>) {
  const active = React.useContext(Selection) === value;
  return (
    <Primitive.Content
      {...props}
      value={value}
      forceMount
      hidden={!active}
      inert={!active}
      data-slot="tabs-content"
      className={cn("roc-ui", className)}
    />
  );
}
export { Tabs, TabsList, TabsTrigger, TabsContent, tabsListVariants };

"use client";
// ROC primitive: tabs with roving focus, automatic or manual activation.
import * as React from "react";
import { composeEventHandlers, useComposedRefs } from "./primitive-utils";
import {
  ROVING_ROOT,
  handleRovingKey,
  useRovingTabStop,
  type Orientation,
} from "./primitive-roving";
import { useControllableState } from "./use-controllable-state";

type Context = {
  baseId: string;
  value: string | undefined;
  setValue: (value: string) => void;
  orientation: Orientation;
  dir?: "ltr" | "rtl";
  activationMode: "automatic" | "manual";
};
const TabsContext = React.createContext<Context | null>(null);
const ListContext = React.createContext<string | null>(null);
const useTabs = () => {
  const context = React.useContext(TabsContext);
  if (!context) throw new Error("Tabs parts must be inside Tabs.Root");
  return context;
};
// Values may contain spaces; ids may not.
const slug = (value: string) => encodeURIComponent(value).replace(/%/g, "_");
const triggerId = (base: string, value: string) => `${base}-trigger-${slug(value)}`;
const contentId = (base: string, value: string) => `${base}-content-${slug(value)}`;

type RootProps = Omit<React.ComponentProps<"div">, "defaultValue" | "dir"> & {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  orientation?: Orientation;
  dir?: "ltr" | "rtl";
  activationMode?: "automatic" | "manual";
};

function Root({
  value: valueProp,
  defaultValue,
  onValueChange,
  orientation = "horizontal",
  dir,
  activationMode = "automatic",
  ...props
}: RootProps) {
  const baseId = React.useId();
  const [value, setValue] = useControllableState<string | undefined>(
    valueProp,
    defaultValue,
    (next) => next !== undefined && onValueChange?.(next),
  );
  return (
    <TabsContext.Provider
      value={{
        baseId,
        value,
        setValue: (next) => setValue(next),
        orientation,
        dir,
        activationMode,
      }}
    >
      <div dir={dir} data-orientation={orientation} {...props} />
    </TabsContext.Provider>
  );
}

function List({ onKeyDown, ref, ...props }: React.ComponentProps<"div">) {
  const context = useTabs();
  const roving = useRovingTabStop('[role="tab"][aria-selected="true"]');
  const composed = useComposedRefs<HTMLDivElement>(ref, roving.ref);
  return (
    <ListContext.Provider value={roving.fallback}>
      <div
        role="tablist"
        aria-orientation={context.orientation}
        data-orientation={context.orientation}
        {...{ [ROVING_ROOT]: "" }}
        {...props}
        ref={composed}
        onKeyDown={composeEventHandlers(onKeyDown, (event) =>
          handleRovingKey(event, roving.ref.current, {
            orientation: context.orientation,
            dir: context.dir,
          }),
        )}
      />
    </ListContext.Provider>
  );
}

type TriggerProps = Omit<React.ComponentProps<"button">, "value"> & {
  value: string;
};

function Trigger({
  value,
  disabled = false,
  onMouseDown,
  onKeyDown,
  onFocus,
  ...props
}: TriggerProps) {
  const context = useTabs();
  const fallback = React.useContext(ListContext);
  const selected = context.value === value;
  return (
    <button
      type="button"
      role="tab"
      aria-selected={selected}
      aria-controls={contentId(context.baseId, value)}
      data-state={selected ? "active" : "inactive"}
      data-disabled={disabled ? "" : undefined}
      data-orientation={context.orientation}
      data-roving-item=""
      data-roving-value={value}
      disabled={disabled}
      tabIndex={selected || fallback === value ? 0 : -1}
      {...props}
      id={triggerId(context.baseId, value)}
      onMouseDown={composeEventHandlers(onMouseDown, (event) => {
        // Select on press, like a native tab strip; never on a modified click.
        if (!disabled && event.button === 0 && !event.ctrlKey)
          context.setValue(value);
        else event.preventDefault();
      })}
      onKeyDown={composeEventHandlers(onKeyDown, (event) => {
        if (event.key === " " || event.key === "Enter") context.setValue(value);
      })}
      onFocus={composeEventHandlers(onFocus, () => {
        if (!selected && !disabled && context.activationMode === "automatic")
          context.setValue(value);
      })}
    />
  );
}

type ContentProps = Omit<React.ComponentProps<"div">, "value"> & {
  value: string;
  /** Keep the panel mounted while inactive. */
  forceMount?: boolean;
};

function Content({ value, forceMount, children, ...props }: ContentProps) {
  const context = useTabs();
  const active = context.value === value;
  if (!active && !forceMount) return null;
  return (
    <div
      role="tabpanel"
      aria-labelledby={triggerId(context.baseId, value)}
      data-state={active ? "active" : "inactive"}
      data-orientation={context.orientation}
      hidden={!active}
      tabIndex={0}
      {...props}
      id={contentId(context.baseId, value)}
    >
      {children}
    </div>
  );
}

export const Tabs = { Root, List, Trigger, Content };

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

"use client";
// ROC primitive: arrow-key focus movement and a single tab stop for a group of items.
// Items mark themselves with `data-roving-item`; each group marks its root `data-roving-root`.
import * as React from "react";

export type Orientation = "horizontal" | "vertical";
export const ROVING_ROOT = "data-roving-root";
export const ROVING_ITEM = "[data-roving-item]";

const INTENT: Record<string, "prev" | "next" | "first" | "last"> = {
  ArrowLeft: "prev",
  ArrowUp: "prev",
  ArrowRight: "next",
  ArrowDown: "next",
  PageUp: "first",
  Home: "first",
  PageDown: "last",
  End: "last",
};

/** Items that belong to this group (not to a nested one) and can take focus. */
export function focusableItems(root: HTMLElement) {
  return Array.from(root.querySelectorAll<HTMLElement>(ROVING_ITEM)).filter(
    (item) =>
      item.closest(`[${ROVING_ROOT}]`) === root &&
      !item.matches(":disabled, [data-disabled]"),
  );
}

/** Move focus for an arrow/Home/End key. Returns whether the key was handled. */
export function handleRovingKey(
  event: React.KeyboardEvent,
  root: HTMLElement | null,
  options: { orientation?: Orientation; dir?: "ltr" | "rtl"; loop?: boolean },
) {
  if (!root || event.metaKey || event.ctrlKey || event.altKey || event.shiftKey)
    return false;
  const current = (event.target as HTMLElement).closest<HTMLElement>(ROVING_ITEM);
  if (!current || current.closest(`[${ROVING_ROOT}]`) !== root) return false;
  const rtl = (options.dir ?? getComputedStyle(root).direction) === "rtl";
  let key = event.key;
  if (rtl && key === "ArrowLeft") key = "ArrowRight";
  else if (rtl && key === "ArrowRight") key = "ArrowLeft";
  const { orientation, loop = true } = options;
  if (orientation === "vertical" && (key === "ArrowLeft" || key === "ArrowRight"))
    return false;
  if (orientation === "horizontal" && (key === "ArrowUp" || key === "ArrowDown"))
    return false;
  const intent = INTENT[key];
  if (!intent) return false;
  event.preventDefault();
  const items = focusableItems(root);
  const index = items.indexOf(current);
  let target: HTMLElement | undefined;
  if (intent === "first") target = items[0];
  else if (intent === "last") target = items[items.length - 1];
  else {
    const step = intent === "next" ? 1 : -1;
    const next = index + step;
    target = loop
      ? items[(next + items.length) % items.length]
      : items[next];
  }
  if (target && target !== current) target.focus();
  return true;
}

/**
 * One tab stop per group: the selected item, or the first enabled item when none
 * is selected. Items read `fallback` and compare it to their `data-roving-value`.
 */
export function useRovingTabStop(selectedSelector: string) {
  const ref = React.useRef<HTMLDivElement | null>(null);
  const [fallback, setFallback] = React.useState<string | null>(null);
  React.useLayoutEffect(() => {
    const root = ref.current;
    if (!root) return;
    const items = focusableItems(root);
    const next = items.some((item) => item.matches(selectedSelector))
      ? null
      : (items[0]?.dataset.rovingValue ?? null);
    setFallback((previous) => (previous === next ? previous : next));
  });
  return { ref, fallback };
}

"use client";
import { useState } from "react";
/** An optional owner, not a mandatory store or application provider. */
export function useControllableState<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (value: T) => void,
): [T, (next: T) => void] {
  const [local, setLocal] = useState(defaultValue),
    current = value === undefined ? local : value;
  return [
    current,
    (next) => {
      if (Object.is(current, next)) return;
      if (value === undefined) setLocal(next);
      onChange?.(next);
    },
  ];
}

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui[data-slot="tabs"] {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}
.roc-ui[data-slot="tabs"][data-orientation="vertical"] {
  flex-direction: row;
}
.roc-ui[data-slot="tabs-list"] {
  display: inline-flex;
  position: relative;
  align-self: flex-start;
  max-width: 100%;
  padding: 3px;
  gap: 2px;
  border-radius: var(--roc-radius, 8px);
  background: var(--roc-marker, #f0f0f0);
  isolation: isolate;
  overflow: auto;
}
.roc-ui[data-slot="tabs-list"][data-orientation="vertical"] {
  flex-direction: column;
  flex-shrink: 0;
}
.roc-ui[data-slot="tabs-trigger"] {
  position: relative;
  z-index: 1;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 6px;
  padding: 9px 13px;
  flex: 1;
  border: 0;
  background: transparent;
  border-radius: max(3px, calc(var(--roc-radius, 8px) - 3px));
  font-size: 12px;
  white-space: nowrap;
  cursor: pointer;
  color: var(--roc-muted, #777);
  transition: color var(--roc-motion-fast) var(--roc-motion-ease);
}
.roc-ui[data-slot="tabs-trigger"][data-state="active"] {
  color: var(--roc-ink, #222);
}
.roc-ui-tabs-marker {
  position: absolute;
  left: 0;
  top: 0;
  pointer-events: none;
  background: var(--roc-paper, #fff);
  border-radius: max(3px, calc(var(--roc-radius, 8px) - 3px));
  box-shadow: 0 1px 3px #00000010;
}
.roc-ui-tabs-marker[data-ready="true"] {
  transition:
    transform var(--roc-motion-fast) var(--roc-motion-ease),
    width var(--roc-motion-fast) var(--roc-motion-ease),
    height var(--roc-motion-fast) var(--roc-motion-ease);
}
.roc-ui[data-slot="tabs-list"][data-variant="line"] {
  background: transparent;
}
.roc-ui[data-slot="tabs-list"][data-variant="line"] .roc-ui-tabs-marker {
  background: transparent;
  box-shadow: inset 0 -2px var(--roc-ink, #222);
  border-radius: 0;
}
.roc-ui[data-slot="tabs-content"] {
  flex: 1;
  min-width: 0;
  line-height: 1.65;
}
.roc-ui[data-slot="tabs-content"][hidden] {
  display: none !important;
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui-tabs-marker,
  .roc-ui[data-slot="tabs-trigger"] {
    transition: none !important;
  }
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}
